#include <stdio.h>
#include "version_info.h"  /* auto-generated by Makefile on every build */

void print_build_info(void)
{
    printf("[ak_rtsp] build #%d | %s | git:%s\n",
           BUILD_NUMBER, BUILD_TIMESTAMP, GIT_HASH);
}

/* LEO 2026-11-24: version string for control port (GET fw.version) */
const char *build_version_string(void)
{
    static char v[96];
    snprintf(v, sizeof(v), "build%d %s %s leo-ota", BUILD_NUMBER, BUILD_TIMESTAMP, GIT_HASH);
    return v;
}
